#[derive(Clone, Debug, Default)]
pub struct VersionOptions {
    pub strict: bool,
    pub allow_empty_changesets: bool,
}

fn map_reason_to_change_source(
    reason: &BumpReason,
    id: &callisto_model::PackageId,
    to: &callisto_model::Version,
    outcome: &crate::cascade::CascadeOutcome,
    agg: &crate::aggregate::Aggregation,
) -> Option<ChangeSource> {
    match reason {
        BumpReason::FixedGroupUnion { group } => Some(ChangeSource::GroupUnion {
            group: group.clone(),
            kind: GroupKind::Fixed,
        }),
        BumpReason::LinkedGroupUnion { group } => Some(ChangeSource::GroupUnion {
            group: group.clone(),
            kind: GroupKind::Linked,
        }),
        // Listed from `CascadeOutcome::dependency_updates`, which covers every bumped dependency, not just the first.
        BumpReason::Cascade { .. } => None,
        BumpReason::PeerEscalation { via, .. } => {
            let dep_to = outcome
                .targets
                .get(via)
                .map_or_else(|| to.clone(), |t| t.version().clone());
            Some(ChangeSource::PeerEscalation {
                dependency: via.clone(),
                to: dep_to,
            })
        }
        BumpReason::Inference { commits, .. } => match agg.inference_commits.get(id).and_then(|c| c.first()) {
            Some((sha, subject)) => Some(ChangeSource::Commit {
                sha: sha.clone(),
                subject: subject.clone(),
            }),
            None => Some(ChangeSource::Changeset {
                filename: String::new(),
                summary: format!("Inferred version bump ({commits} commit(s))"),
            }),
        },
        _ => None,
    }
}

/// One "Dependency updates" entry per bumped dependency `id` was updated for, at the version it actually reached.
fn dependency_update_entries(
    id: &callisto_model::PackageId,
    severity: Severity,
    outcome: &crate::cascade::CascadeOutcome,
) -> Vec<ChangelogEntry> {
    let Some(updates) = outcome.dependency_updates.get(id) else {
        return Vec::new();
----
        ws.git_access(),
        tags,
        &base_versions,
        pre_state.as_ref(),
        inference,
    )?;

    let mut seed = agg.severities();
    let mut reasons = agg.reasons();
    // PreMode::Exit: seed a Patch for every pre-release package so `bump_target` finalizes it though the changesets were consumed.
    if let Some(ref pre) = pre_state
        && pre.mode == callisto_model::format::PreMode::Exit
    {
        for (id, ver) in &base_versions {
            if ver.is_prerelease() {
                seed.entry(id.clone()).or_insert(Severity::Patch);
                reasons
                    .entry(id.clone())
                    .or_insert(BumpReason::PreRelease { tag: pre.tag.clone() });
            }
        }
    }

    let input = CascadeInput {
        graph: &ws.graph,
        groups: &ws.config.groups,
        cfg: &ws.config.cascade,
        seed: &seed,
        reasons: &reasons,
        base: &base_versions,
        pre: pre_state.as_ref(),
        tags,
        identity: &ws.identity,
    };

    let napi = crate::napi::NapiTargetsIndex::load(&ws.config.groups, &ws.root, &ws.graph)?;
    let group_check = crate::groups::pre_mutation_checks(&ws.config.groups, &base_versions, tags, &napi, &ws.root)?;

    let outcome = run_cascade(input)?;

    let mut bumps = Vec::new();
    let mut changelog_writes = Vec::new();

    // PERF-006: build a map once so each lookup inside the loop is O(1)
    // instead of O(N) (the previous packages().find() call).
    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();

    for (id, &sev) in &outcome.severities {
        if sev == Severity::None {
            continue;
        }
        let pkg = pkg_map
            .get(id)
            .copied()
            .expect("every bumped package is in the workspace");
        let from = base_versions.get(id).cloned().ok_or_else(|| {
            GraphError::Manifest(callisto_model::ManifestError::MissingField {
                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
                field: "version",
            })
        })?;
        let to = outcome.targets.get(id).map(|t| t.version().clone()).ok_or_else(|| {
            GraphError::Manifest(callisto_model::ManifestError::MissingField {
                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
                field: "version",
            })
        })?;

        let mut writes = Vec::new();
        for decl in &pkg.manifests {
            if decl.role == callisto_model::ManifestRole::Canonical {
                writes.push(VersionWriteTarget::Manifest(decl.path.clone()));
            }
        }

        bumps.push(PlannedBump {
            package: id.clone(),
            from: from.clone(),
            to: to.clone(),
            severity: sev,
            governed_by: outcome.governed_by.get(id).cloned(),
            reason: outcome.reasons.get(id).cloned(),
            writes,
        });

        if let Some(ch_path) = &pkg.changelog {
            let mut input = match agg.changelog_inputs.get(id).cloned() {
                Some(mut agg_input) => {
                    // Real changeset data: use it, but set the resolved target version.
                    agg_input.from = from.clone();
                    agg_input.to = Some(to.clone());
                    if let Some(reason) = outcome.reasons.get(id)
                        && let Some(source) = map_reason_to_change_source(reason, id, &to, &outcome, &agg)
                    {
                        agg_input.entries.push(ChangelogEntry { severity: sev, source });
                    }
                    agg_input.entries.extend(dependency_update_entries(id, sev, &outcome));
                    agg_input
                }
                _ => {
                    // No changeset drove this bump (cascade, group, inference, pre-release).
                    // Synthesize a single entry describing the reason so that render_section()
                    // never receives an empty entries list (which returns EmptyInput).
                    let mut entries: Vec<ChangelogEntry> = outcome
                        .reasons
                        .get(id)
                        .and_then(|r| map_reason_to_change_source(r, id, &to, &outcome, &agg))
                        .map(|source| ChangelogEntry { severity: sev, source })
                        .into_iter()
                        .collect();
                    entries.extend(dependency_update_entries(id, sev, &outcome));
                    if entries.is_empty() {
                        let source = ChangeSource::Changeset {
                            filename: String::new(),
                            summary: format!(
                                "Version bump ({})",
                                match sev {
                                    Severity::Major => "major",
                                    Severity::Minor => "minor",
                                    Severity::Patch => "patch",
                                    Severity::None => "none",
                                }
                            ),
                        };
                        entries.push(ChangelogEntry { severity: sev, source });
                    }
                    ChangelogInput {
                        style: ChangelogStyle::default(),
                        package: id.clone(),
                        from: from.clone(),
                        to: Some(to.clone()),
                        entries,
                    }
                }
            };

            input.style = changelog_style(ws, repository.as_ref(), tags, id, &from, &to, date);

            if let Some(group_name) = group_check
                .new_members
                .iter()
                .find(|(_, members)| members.contains(id))
                .map(|(name, _)| name.clone())
            {
                input.entries.push(ChangelogEntry {
                    severity: sev,
                    source: ChangeSource::NewGroupMember { group: group_name },
                });
            }

            changelog_writes.push(crate::plan::ChangelogWrite {
    pub new_pre_changesets: Vec<String>,
    /// Changeset files a Changesets v3 pre cycle moves into `.changeset/pre/` this run, marking them applied.
    pub archived: Vec<crate::plan::ArchivedChangeset>,
    pub changelog_inputs: BTreeMap<PackageId, ChangelogInput>,
    pub inference_commits: BTreeMap<PackageId, Vec<(CommitSha, String)>>,
    pub diagnostics: Vec<Diagnostic>,
}

impl Aggregation {
    /// Each seeded package's severity, the cascade's starting point.
    pub fn severities(&self) -> BTreeMap<PackageId, Severity> {
        self.seeds
            .iter()
            .map(|(id, seed)| (id.clone(), seed.severity()))
            .collect()
    }

    /// Each seeded package's reason.
    pub fn reasons(&self) -> BTreeMap<PackageId, BumpReason> {
        self.seeds
            .iter()
            .map(|(id, seed)| (id.clone(), seed.reason()))
            .collect()
    }

    fn add(&mut self, id: &PackageId, severity: Severity, source: Source) {
        match self.seeds.get_mut(id) {
            Some(seed) => seed.add(severity, source),
            None => {
                self.seeds.insert(id.clone(), Seed::new(severity, source));
            }

